/**
 * Shared state for the smoke-test stubs. The agent-event bus is the only piece
 * that both `agent-runtime` and `agent-harness-runtime` need to see.
 */
const listeners = new Set();

export function subscribe(listener) {
  listeners.add(listener);
  return () => listeners.delete(listener);
}

export function emit(event) {
  for (const listener of [...listeners]) {
    listener(event);
  }
}

/** Set by the harness; called by the fake agent runtime. */
export let agentImpl = async () => {};

export function setAgentImpl(fn) {
  agentImpl = fn;
}
